// Тратит одну награду; бусты user4 растут на 1 (не откатить) — аннотация cleanup. Не проверен на живой странице.
import { test, expect } from '../../fixtures';
import { saveSession } from '../_shared/session';
import { phone, openStreak, earnedCount, openPicker, chooseReward, claimButton, isWrite } from './streak-helpers';

test.describe('Серия: получение награды «בוסט»', () => {
  test.describe.configure({ mode: 'serial', timeout: 180_000 });

  test('«בוסט»: «בוסט נוסף לחשבון שלך», «פרסים שצברת» +1; повтор того же получения отклонён; без наград — «אין כרגע פרס למימוש» @iphone @data (#808adb #fdc5b2 #a55519)', async ({ asUser }) => {
    const p = await asUser('user4');
    let claimed = false;
    try {
      await phone(p);
      await openStreak(p);
      const before = await earnedCount(p, /בוסטים?/);

      await openPicker(p);
      await expect(p.getByText(/בוחרים פרס אחד מתוך ארבעה/)).toBeVisible();
      await chooseReward(p, 'בוסט');
      const w = p.waitForResponse(isWrite);
      await claimButton(p).click();
      const res = await w;
      expect(res.ok(), `получение награды: ${res.status()} ${await res.text()}`).toBeTruthy();
      claimed = true;
      await expect(p.getByText('בוסט נוסף לחשבון שלך')).toBeVisible({ timeout: 15_000 });
      const more = await p.getByText('נשאר עוד פרס אחד').isVisible();

      // Повтор того же запроса — сервер отказывает (одна награда на цель, #808adb AC 3).
      const req = res.request();
      const h = await req.allHeaders();
      const again = await p.request.fetch(req.url(), {
        method: req.method(),
        headers: { apikey: h['apikey'], authorization: h['authorization'], 'content-type': 'application/json' },
        data: req.postData() ?? undefined,
        failOnStatusCode: false,
      });
      expect(again.ok(), `повтор получения должен быть отклонён: ${again.status()} ${await again.text()}`).toBeFalsy();

      // Закрыть и проверить баланс +1 (#808adb AC 6).
      await p.getByRole('button', { name: 'סיום' }).click();
      await openStreak(p);
      await expect.poll(() => earnedCount(p, /בוסטים?/), { timeout: 30_000 }).toBe(before + 1);

      // Если наград не осталось — пустое состояние (#fdc5b2 AC 4).
      if (!more) {
        await expect(p.getByText('פרס אחד מחכה לך')).toHaveCount(0);
      }
    } finally {
      if (claimed) test.info().annotations.push({ type: 'cleanup', description: 'user4: награда серии потрачена на «בוסט» (+1 буст) — не откатить; для следующего прогона выдать «הענקת תגמול רצף» в админке' });
      await saveSession(p, 'user4');
    }
  });
});
